d AtDelete(ArrayIndex_AC index);#else	inline void AtDelete(ArrayIndex_AC index)	{ DeleteElementsAt(index, 1); }#endif		// Deletes via an index.	virtual void Delete(const DatabaseBlockHeader& item);	DatabaseBlockHeader First() const;		// Return the first element of the list. If the compile-flag qDebug is true &        // SetEltType was called, verify item's type.	DatabaseBlockHeader Last() const;		// Return the last element of the list. If the compile-flag qDebug is true &        // SetEltType was called, verify item's type.	virtual ArrayIndex_AC GetIdentityItemNo(const DatabaseBlockHeader& item) const;		// Find the first reference to the IDENTITY item in the list. If item does not        // occur, return 0.	virtual ArrayIndex_AC GetEqualItemNo(const DatabaseBlockHeader& item) const;		// Find the first reference to item in the list. If item does not occur, return 0.	virtual CompareResult_AC Compare(const DatabaseBlockHeader& item1, const DatabaseBlockHeader& item2) const;		// By default just compare the ordinal value of the items. Subclasses that want to        // use the items as pointers or other types should override if the comparison is        // based on the pointed at value	virtual CompareResult_AC CompareElements(const void* element1, const void* element2) const;		// Forward into the Compare function.	virtual Boolean DoSearch(CompareBlockHeaderProc TestItem, void* yourDataPtr, ArrayIndex_AC& index) const;		// DON'T use EXIT to get out of this routine from your TestItem function or you        // will be really sad!(our debugger will check for you) That's why you can return        // true to stop enumerating. Signaling Failure is OK too.	virtual ArrayIndex_AC Search(CompareBlockHeaderProc TestItem, void* yourDataPtr) const;	ArrayIndex_AC FindItem(OSType kind, long id);		// Find a matching item in the list. 	// I/O Support	ArrayIndex_AC BytesToCount(long size) const;		// Convert an array size in bytes to the count of elements in it. 	long ElementBytes() const;		// Get the full size of an element. 	void SetSize(ArrayIndex_AC count);		// Set the count of elements in the array. 	ArrayIndex_AC GetSizeInBytes();		// Get the array size in bytes. 	// Indexed Access	long CountKinds() const;	OSType GetIndKind(long index) const;	long CountItems(OSType kind) const;	long GetIndItemID(OSType kind, long index) const;	long UniqueItemID(OSType kind) const;  protected:	//====================================================================================	// TDatabaseDirectory::CSearch	//====================================================================================	struct CSearch	{	  public:		CompareBlockHeaderProc&	fTestItemProc;		void*&					fStaticLink;		DatabaseBlockHeader&	fItem;		const TDatabaseDirectory*	fList;		// Constructor		inline CSearch(CompareBlockHeaderProc& TestItem,					   void*& yourDataPtr,					   DatabaseBlockHeader& theItem,					   const TDatabaseDirectory* theList) :			fTestItemProc(TestItem),			fStaticLink(yourDataPtr),			fItem(theItem),			fList(theList)		{ }		static CompareResult_AC TestElement(ArrayIndex_AC anItem, void* yourDataPtr);	};	//====================================================================================	// TDatabaseDirectory::CCompare	//====================================================================================	struct CCompare	{	  public:		const DatabaseBlockHeader&	fCompareWith;		const TDatabaseDirectory*	fList;		// Constructor		inline CCompare(const DatabaseBlockHeader& theItem,						const TDatabaseDirectory* theList) :			fCompareWith(theItem),			fList(theList)		{ }		static CompareResult_AC CompareItems(const DatabaseBlockHeader& anItem, void* yourDataPtr);	};};//========================================================================================// TDatabaseFile//========================================================================================class TDatabaseFile : public TFile{  protected:	TDatabaseDirectory*	fDirectory;			// directory of database blocks	DatabaseBlockHeader	fHeader;			// header block for the database	long				fBlockIncrement;	// round up block allocation	Boolean				fChangedDirectory;	// directory needs to be written	Boolean				fChangedHeader;		// header needs to be written  public:	// Construction/Destruction	TDatabaseFile(OSType itsFileType, OSType itsCreator,				  ResourceUsage usesRsrcFork,				  Boolean keepsDataOpen, Boolean keepsRsrcOpen,				  long blockIncrement);	virtual ~TDatabaseFile();	// Closing	virtual OSErr CloseDataFork();	// Header	void ReadHeader();	void WriteHeader();	// Directory	void ReadDirectory();	void WriteDirectory();	// Block	Boolean ValidBlock(const DatabaseBlockHeader& block);	Handle ReadBlock(const DatabaseBlockHeader& block);	void ReadBlock(const DatabaseBlockHeader& block, void *data, long size, long *actualSize);	void WriteBlockHeader(const DatabaseBlockHeader& block);	void WriteBlock(const DatabaseBlockHeader& block, const Handle data);	void WriteBlock(const DatabaseBlockHeader& block, const void *data);	void AllocateBlock(DatabaseBlockHeader& block);	long AllocationSize(long used) const;	void FreeBlock(const DatabaseBlockHeader& block);	void EraseBlock(const DatabaseBlockHeader& block);	OSErr EraseData(unsigned long count);	// Items	ArrayIndex_AC FindItem(OSType kind, long id);	Handle ReadItem(OSType kind, long id);	void ReadItem(OSType kind, long id, void *data, long size,				  long *actualSize);	void WriteItem(OSType kind, long id, const Handle data);	void WriteItem(OSType kind, long id, const void *data, long size);	void AllocateItem(OSType kind, long id, long size,					  DatabaseBlockHeader& block);	void DeleteItem(OSType kind, long id);	// Copying	void CopyDatabase(TDatabaseFile* fromDatabase);	long DoNeedDiskSpace() const;	// Indexed Access	long CountKinds();	OSType GetIndKind(long index);	long CountItems(OSType kind);	long GetIndItemID(OSType kind, long index);	long UniqueItemID(OSType kind);};#endif // __UDATABASEFILE__